// Keep account, onboarding and exam on their verified paths during the UI migration.
(()=>{function open(){const a=window.BoraAccount,u=a?.state;if(!a?.ready||!a.signedIn||a.error||a.recovery||!u?.onboarded||/Сохраняю|Не сохранено|другом устройстве/.test(a.status||''))return;const route=location.hash.slice(1)||'home';let destination;if(route==='home')destination='/learn/';else if(route==='courses/pt')destination='/learn/program';else if(route==='dictionary')destination='/learn/dictionary';else if(route==='progress')destination='/learn/progress';if(destination){clearInterval(timer);location.replace(destination)}}const timer=setInterval(open,1000);window.addEventListener('pagehide',()=>clearInterval(timer));window.addEventListener('hashchange',open);open()})();
